void start(const Pcm16& clip) noexcept {
    clip_ = &clip;
    cursor_ = 0;
    active_ = clip.layout().frames > 0;
}


void stop() noexcept {
    clip_ = nullptr;
    cursor_ = 0;
    active_ = false;
}

void render(void* out, std::size_t bytes) noexcept {
    auto* dst = static_cast<std::uint8_t*>(out);
    if (bytes == 0) return;
    std::memset(dst, 0, bytes);
    if (!active_ || clip_ == nullptr) return;

    const std::size_t channels = clip_->channels();
    const std::size_t bytes_per_frame = channels * sizeof(std::int16_t);
    if (bytes_per_frame == 0) return;

    const std::size_t frames = clip_->layout().frames;
    const std::size_t wanted = bytes / bytes_per_frame;
    const std::size_t available = cursor_ < frames ? frames - cursor_ : 0;
    const std::size_t copy_frames = wanted < available ? wanted : available;

    if (copy_frames > 0) {
        std::memcpy(dst,
                    clip_->samples().data() + cursor_ * channels,
                    copy_frames * bytes_per_frame);
        cursor_ += copy_frames;
    }
    if (cursor_ >= frames) active_ = false;
}

auto clip = study_audio::make_reference_tone();
study_audio::Voice a, b;
a.start(clip);
b.start(clip);
unsigned char first[8], second[4];
a.render(first, sizeof first);
b.render(second, sizeof second);
// a.cursor_frames() == 2, b.cursor_frames() == 1
// clip은 a와 b가 연결된 동안 살아 있고 변경되지 않는다.
a.stop();
b.stop();

Player::State Player::state() const noexcept {
    if (dev_ == 0) return State::closed;
    DeviceLock lock(dev_);
    if (!clip_.has_value()) return State::empty;
    if (voice_.playing()) return State::playing;
    if (voice_.cursor_frames() >= clip_->layout().frames) return State::finished;
    return State::ready;
}

bool Player::open(std::uint32_t rate, std::uint32_t channels) noexcept {
    if (dev_ != 0) return false;
    if (rate == 0 || channels == 0) return false;
    // The PCM layer is the authority on what a valid S16 format is.
    if (!audio_pcm::layout_s16(1, channels, rate).has_value()) return false;

    if (SDL_InitSubSystem(SDL_INIT_AUDIO) != 0) return false;

    SDL_AudioSpec want;
    SDL_zero(want);
    want.freq = static_cast<int>(rate);
    want.format = AUDIO_S16SYS;
    want.channels = static_cast<Uint8>(channels);
    want.samples = 512;
    want.callback = &Player::callback;
    want.userdata = this;

    SDL_AudioSpec have;
    SDL_zero(have);
    const SDL_AudioDeviceID dev =
        SDL_OpenAudioDevice(nullptr, 0, &want, &have, 0);
    if (dev == 0) {
        SDL_QuitSubSystem(SDL_INIT_AUDIO);
        return false;
    }
    if (have.freq != want.freq || have.format != want.format ||
        have.channels != want.channels) {
        SDL_CloseAudioDevice(dev);
        SDL_QuitSubSystem(SDL_INIT_AUDIO);
        return false;
    }

    dev_ = dev;
    rate_ = rate;
    channels_ = channels;
    owns_audio_ = true;
    // Opened paused; userdata is fully set before any unpause.
    return true;
}

Player(const Player&) = delete;
Player& operator=(const Player&) = delete;
Player(Player&&) = delete;
Player& operator=(Player&&) = delete;

void Player::callback(void* userdata, Uint8* out, int len) noexcept {
    if (len <= 0) return;
    auto* self = static_cast<Player*>(userdata);
    self->voice_.render(out, static_cast<std::size_t>(len));
}

class DeviceLock {
public:
    explicit DeviceLock(SDL_AudioDeviceID dev) noexcept : dev_(dev) {
        if (dev_ != 0) SDL_LockAudioDevice(dev_);
    }
    ~DeviceLock() noexcept {
        if (dev_ != 0) SDL_UnlockAudioDevice(dev_);
    }
    DeviceLock(const DeviceLock&) = delete;
    DeviceLock& operator=(const DeviceLock&) = delete;

private:
    SDL_AudioDeviceID dev_;
}
;

bool Player::replace(Pcm16&& clip) noexcept {
    // Validate before touching the old clip so a failed call preserves it.
    if (dev_ == 0) return false;
    if (clip.layout().frames == 0) return false;
    if (clip.rate() != rate_ || clip.channels() != channels_) return false;
    if (!audio_pcm::layout_s16(1, clip.channels(), clip.rate()).has_value())
        return false;

    DeviceLock lock(dev_);
    voice_.stop();
    clip_.emplace(std::move(clip));
    return true;
}

void Player::stop() noexcept {
    if (dev_ == 0) return;
    SDL_PauseAudioDevice(dev_, 1);
    DeviceLock lock(dev_);
    voice_.stop();
}


void Player::unload() noexcept {
    if (dev_ == 0) return;
    SDL_PauseAudioDevice(dev_, 1);
    DeviceLock lock(dev_);
    voice_.stop();
    clip_.reset();
}


void Player::close() noexcept {
    if (dev_ == 0) return;
    // Stop the callback first: it borrows both `this` and `clip_`.
    SDL_CloseAudioDevice(dev_);
    voice_.stop();
    clip_.reset();
    dev_ = 0;
    if (owns_audio_) {
        SDL_QuitSubSystem(SDL_INIT_AUDIO);
        owns_audio_ = false;
    }
}

std::printf("submitted frames=%zu\n", player.cursor_frames());
player.stop();
player.unload();
player.close();

